using UnityEngine;
using UnityEngine.UI;
using UnityEditor;

public class ReplaceAllFonts
{
    public static string Main()
    {
        var sb = new System.Text.StringBuilder();
        int countScene = 0;
        int countPrefabs = 0;

        // 1. Load the new font
        Font newFont = AssetDatabase.LoadAssetAtPath<Font>("Assets/Font/Poppins-Light.ttf");
        if (newFont == null)
        {
            return "ERROR: Font Poppins-Light.ttf tidak ditemukan di Assets/Font/";
        }

        // 2. Ganti font di semua object di Active Scene
        var textsInScene = Object.FindObjectsByType<Text>(FindObjectsInactive.Include, FindObjectsSortMode.None);
        foreach (var text in textsInScene)
        {
            if (text.font != newFont)
            {
                text.font = newFont;
                EditorUtility.SetDirty(text);
                countScene++;
            }
        }
        if (countScene > 0)
        {
            UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(UnityEngine.SceneManagement.SceneManager.GetActiveScene());
            sb.AppendLine($"[OK] Berhasil mengganti {countScene} teks di Scene.");
        }

        // 3. Ganti font di semua Prefabs di project
        string[] prefabGuids = AssetDatabase.FindAssets("t:Prefab");
        foreach (string guid in prefabGuids)
        {
            string path = AssetDatabase.GUIDToAssetPath(guid);

            // Skip certain Unity packages if necessary
            if (path.StartsWith("Packages/")) continue;

            GameObject prefab = AssetDatabase.LoadAssetAtPath<GameObject>(path);
            if (prefab == null) continue;

            bool changed = false;
            var textsInPrefab = prefab.GetComponentsInChildren<Text>(true);
            foreach (var text in textsInPrefab)
            {
                if (text.font != newFont)
                {
                    text.font = newFont;
                    EditorUtility.SetDirty(text);
                    changed = true;
                    countPrefabs++;
                }
            }

            if (changed)
            {
                PrefabUtility.SavePrefabAsset(prefab);
            }
        }

        if (countPrefabs > 0)
        {
            sb.AppendLine($"[OK] Berhasil mengganti {countPrefabs} teks di dalam Prefabs.");
        }

        if (countScene == 0 && countPrefabs == 0)
        {
            sb.AppendLine("[INFO] Semua teks sudah menggunakan font Poppins.");
        }

        AssetDatabase.SaveAssets();
        return sb.ToString();
    }
}
